const SCRIBBLE = 'M-346.0 738.0 C-342.4 758.0 -331.6 760.0 -328.0 756.0 C-323.7 752.0 -317.2 726.0 -310.0 726.0 C-306.4 758.0 -295.6 760.0 -292.0 756.0 C-287.7 752.0 -281.2 712.0 -274.0 712.0 C-270.4 758.0 -259.6 760.0 -256.0 756.0 C-251.7 752.0 -245.2 730.0 -238.0 730.0 C-234.4 758.0 -223.6 760.0 -220.0 756.0 C-215.7 752.0 -209.2 718.0 -202.0 718.0 C-198.4 758.0 -187.6 760.0 -184.0 756.0 C-179.7 752.0 -173.2 706.0 -166.0 706.0 C-162.4 758.0 -151.6 760.0 -148.0 756.0 C-143.7 752.0 -137.2 728.0 -130.0 728.0 C-126.4 758.0 -115.6 760.0 -112.0 756.0 C-107.7 752.0 -101.2 722.0 -94.0 722.0 C-90.4 758.0 -79.6 760.0 -76.0 756.0 C-71.7 752.0 -65.2 714.0 -58.0 714.0 C-54.4 758.0 -43.6 760.0 -40.0 756.0 C-35.7 752.0 -29.2 732.0 -22.0 732.0 C-16.0 742.0 8.0 754.0 14.0 752.0';
const TIP = { x: 14.0, y: 752.0 };

const DRAW_MS = 2800;
const BACK_MS = 800;
const FRAMES = 96;
const VIEW = { x: -380, y: 30, w: 1390, h: 980 };
const WIDTH = 9;

function svgEl<K extends keyof SVGElementTagNameMap>(name: K): SVGElementTagNameMap[K] {
  return document.createElementNS(NS, name);
}

function layer(): SVGSVGElement {
  const svg = svgEl('svg');
  svg.setAttribute('viewBox', `${VIEW.x} ${VIEW.y} ${VIEW.w} ${VIEW.h}`);
  return svg;
}

function smooth(t: number): number {
  return t * t * (3 - 2 * t);
}

function writing(t: number): number {
  const base = 0.12 * smooth(t) + 0.88 * t;
  return Math.min(1, Math.max(0, base + 0.011 * Math.sin(t * Math.PI * 2 * 9)));
}

type Moment = { drawn: number; alpha: number; back: number };

function moment(frame: number): Moment {
  const ms = (frame / FRAMES) * (DRAW_MS + BACK_MS);
  if (ms <= DRAW_MS) return { drawn: writing(ms / DRAW_MS), alpha: 1, back: 0 };
  const r = (ms - DRAW_MS) / BACK_MS;
  return { drawn: 1, alpha: 1 - smooth(Math.min(1, r * 3.2)), back: smooth(Math.max(0, (r - 0.3) / 0.7)) };
}

function lineStrip(length: number, width: number): Promise<string> {
  const scale = (width * Math.max(2, window.devicePixelRatio || 1)) / VIEW.w;
  const fw = Math.round(VIEW.w * scale);
  const fh = Math.round(VIEW.h * scale);
  const canvas = document.createElement('canvas');
  canvas.width = fw;
  canvas.height = fh * FRAMES;
  const ctx = canvas.getContext('2d')!;
  const shape = new Path2D(SCRIBBLE);
  ctx.strokeStyle = INK;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  for (let f = 0; f < FRAMES; f++) {
    const { drawn, alpha } = moment(f);
    const shown = drawn * length;
    if (shown <= 0.5 || alpha <= 0.01) continue;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.translate(0, f * fh);
    ctx.scale(scale, scale);
    ctx.translate(-VIEW.x, -VIEW.y);
    ctx.lineWidth = WIDTH;
    ctx.setLineDash([shown, length + 10]);
    ctx.stroke(shape);
    ctx.restore();
  }
  return new Promise((resolve) => canvas.toBlob((blob) => resolve(blob ? URL.createObjectURL(blob) : ''), 'image/png'));
}

export function sketchingAnimation(container: HTMLElement): void {
  const box = document.createElement('div');
  box.className = 'sketching-art';
  box.setAttribute('aria-hidden', 'true');
  const ink = document.createElement('div');
  ink.className = 'ink';
  const strip = document.createElement('img');
  strip.alt = '';
  ink.append(strip);
  const handLayer = layer();
  handLayer.classList.add('hand');
  for (const [d, rule] of HAND) {
    const el = svgEl('path');
    el.setAttribute('d', d);
    el.setAttribute('fill', INK);
    el.setAttribute('fill-rule', rule);
    handLayer.append(el);
  }
  box.append(ink, handLayer);
  container.prepend(box);

  const measure = layer();
  measure.style.cssText = 'position:absolute;width:0;height:0;visibility:hidden';
  const line = svgEl('path');
  line.setAttribute('d', SCRIBBLE);
  measure.append(line);
  document.body.append(measure);
  const length = line.getTotalLength();
  const start = line.getPointAtLength(0);
  const offsets = Array.from({ length: FRAMES + 1 }, (_, f) => {
    const { drawn, back } = moment(f);
    if (back > 0) {
      const lift = Math.sin(back * Math.PI) * 38;
      return { x: (start.x - TIP.x) * back, y: (start.y - TIP.y) * back - lift };
    }
    const p = line.getPointAtLength(drawn * length);
    return { x: p.x - TIP.x, y: p.y - TIP.y };
  });
  offsets[FRAMES] = offsets[0];
  measure.remove();

  const still = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const duration = DRAW_MS + BACK_MS;
  let animations: Animation[] = [];

  const begin = async () => {
    const width = box.clientWidth || 78;
    strip.src = await lineStrip(length, width);
    const pct = (o: { x: number; y: number }) =>
      `translate(${((o.x / VIEW.w) * 100).toFixed(2)}%, ${((o.y / VIEW.h) * 100).toFixed(2)}%)`;
    if (still) {
      strip.style.transform = `translateY(${(-Math.round(FRAMES * (DRAW_MS / duration)) / FRAMES) * 100}%)`;
      return;
    }
    const hand = handLayer.animate(
      offsets.map((o, f) => ({ offset: f / FRAMES, transform: pct(o) })),
      { duration, iterations: Infinity, easing: 'linear' },
    );
    const frames = strip.animate([{ transform: 'translateY(0)' }, { transform: 'translateY(-100%)' }], {
      duration,
      iterations: Infinity,
      easing: `steps(${FRAMES})`,
    });
    animations = [hand, frames];
  };
  const ready = begin();

  const update = async () => {
    await ready;
    for (const a of animations) {
      if (container.hidden) a.pause();
      else {
        a.currentTime = 0;
        a.play();
      }
    }
  };

  new MutationObserver(update).observe(container, { attributes: true, attributeFilter: ['hidden'] });
}
